{
  "_comment": "Pre-written answers the Tier 3 live driver feeds to the workflow so no person is needed. The pitch and roles come from frontend/docs/requirements.md. This is a pure prototype — all server behaviour (auth, persistence, email) is simulated client-side (see requirements.md Prototype invariants).",

  "benchmark": "contact-form",

  "intake": {
    "pitch": "A Contact & Enquiry Management app. A Visitor submits a contact enquiry (name, email, optional address, a category — Feedback / Question / General Enquiry — and a comment) and gets an immediate confirmation with the form cleared. A Support Agent works incoming enquiries from an inbox, moving each through New / In Progress / Resolved (a resolve requires a reply note). An Admin can additionally delete enquiries. Enquiries are role-scoped: a Visitor sees only their own.",
    "roles": [
      { "name": "Visitor", "can": ["submit an enquiry", "view their own submissions", "sign in"], "cannot": ["see the inbox", "see other people's enquiries", "change status", "delete"] },
      { "name": "Support Agent", "can": ["view all enquiries", "search/filter", "change status (New -> In Progress -> Resolved)", "resolve with a reply note"], "cannot": ["submit on the public form", "delete"] },
      { "name": "Admin", "can": ["everything a Support Agent can", "delete an enquiry"], "cannot": ["submit on the public form"] }
    ],
    "signIn": {
      "choice": "your own server (BFF)",
      "options": ["your own server (BFF)", "a hosted sign-in provider", "no sign-in / stub"],
      "rationale": "The app is role-gated (Visitor vs Support Agent vs Admin) with role-based landing, RBAC action-hiding, and a permission-denied banner on direct links — so it needs authenticated roles to exercise. BFF matches the template's auth policy; the auth itself is simulated client-side per the prototype invariants (no real backend)."
    },
    "dataSource": {
      "note": "No backend service. Build against in-memory fixtures derived from the requirements (a handful of seeded enquiries across the three categories and statuses, plus the seeded users below). All server behaviour is simulated client-side.",
      "seededUsers": ["visitor@example.com / Test123 (Visitor)", "agent@example.com / Test123 (Support Agent)", "admin@example.com / Test123 (Admin)"]
    },
    "compliance": {
      "regulatedData": false,
      "note": "Collects personal data (name, email, optional address). Not a regulated domain, but enquiries must be visible only to authenticated back-office roles, never to other Visitors."
    },
    "styling": {
      "source": null,
      "note": "No bespoke design system. Use the template's Shadcn defaults with a clean, neutral palette and centralised styling tokens."
    }
  },

  "approvals": {
    "intakeApproval": { "action": "approve", "note": "Approve the project facts + epic plan once shown." },
    "storyApproval": { "action": "approve", "note": "Approve the story list once shown." },
    "handsOnApproval": {
      "action": "approve",
      "perPartChecks": [
        "Visitor can submit an enquiry and sees 'Message sent!' with the form cleared",
        "Support Agent sees the new enquiry in the inbox and can move it New -> In Progress",
        "Resolving an enquiry requires a non-empty reply note",
        "Visitor cannot reach the inbox (direct link shows a permission-denied banner)",
        "Admin can delete an enquiry behind a confirmation; the Agent has no Delete action"
      ],
      "note": "Role-observable checks ticked at MANUAL-TEST."
    },
    "mergeApproval": { "action": "approve", "note": "Approve the merge into main once EPIC-END is green." }
  }
}

