16	import { API_BASE_URL } from '@/lib/utils/constants';
17	import type {
18	  APIError,
19	  APIRequestConfig,
20	  DefaultResponse,
21	  HTTPStatusCode,
22	  QueryParams,
23	} from '@/types/api';
