25	/**
26	 * Main API client function that wraps fetch with error handling and logging
27	 *
28	 * @param endpoint - API endpoint path (e.g., '/v1/resource')
29	 * @param config - Request configuration including method, body, headers, etc.
30	 * @returns Promise with parsed JSON response
31	 * @throws APIError on HTTP errors or network failures
32	 */
33	export async function apiClient<T = unknown>(
34	  endpoint: string,
35	  config: APIRequestConfig = {},
36	): Promise<T> {
37	  const {
38	    params,
39	    lastChangedUser,
40	    isBinaryResponse,
41	    requiresAuth,
42	    ...fetchConfig
43	  } = config;
44	
45	  // Build full URL with query parameters
46	  const url = buildUrl(endpoint, params);
47	
48	  // Build headers
49	  const headers = buildHeaders(
50	    fetchConfig.method,
51	    lastChangedUser,
52	    fetchConfig.headers,
53	    fetchConfig.body ?? undefined,
54	    requiresAuth,
55	  );
56	
57	  // Log request in development
58	  logRequest(url, fetchConfig.method || 'GET', fetchConfig.body ?? undefined);
59	
60	  try {
61	    const response = await fetch(url, {
62	      ...fetchConfig,
63	      headers,
64	      body: fetchConfig.body ?? undefined,
65	    });
66	
67	    // Log response in development
68	    logResponse(response);
69	
70	    // Handle specific error status codes
71	    if (!response.ok) {
72	      await handleErrorResponse(response, url);
73	    }
74	
75	    // Handle successful responses
76	    return await handleSuccessResponse<T>(response, isBinaryResponse);
77	  } catch (error) {
78	    // Handle network errors or other unexpected errors
79	    if (error instanceof Error && error.name === 'TypeError') {
80	      throw createAPIError(
81	        'Network error: Unable to connect to the API server',
82	        0,
83	        ['Please check your internet connection and try again.'],
84	        url,
85	      );
86	    }
87	
88	    // Re-throw API errors
89	    throw error;
90	  }
91	}
