128	/**
129	 * Builds request headers
130	 * Only sets Content-Type when there's a request body
131	 * Injects auth header from getAuthHeader() when requiresAuth is true and an
132	 * explicit override isn't already present in customHeaders
133	 */
134	function buildHeaders(
135	  method?: string,
136	  lastChangedUser?: string,
137	  customHeaders?: HeadersInit,
138	  body?: BodyInit,
139	  requiresAuth?: boolean,
140	): Record<string, string> {
141	  const baseHeaders: Record<string, string> = {};
142	
143	  // Convert HeadersInit to plain object if needed
144	  if (customHeaders) {
145	    if (customHeaders instanceof Headers) {
146	      customHeaders.forEach((value, key) => {
147	        baseHeaders[key] = value;
148	      });
149	    } else if (Array.isArray(customHeaders)) {
150	      customHeaders.forEach(([key, value]) => {
151	        baseHeaders[key] = value;
152	      });
153	    } else {
154	      Object.assign(baseHeaders, customHeaders);
155	    }
156	  }
157	
158	  // Only set Content-Type for requests with a body
159	  const hasBody = body !== undefined;
160	  const methodsWithBody = ['POST', 'PUT', 'PATCH'];
161	  const shouldSetContentType =
162	    hasBody || (method && methodsWithBody.includes(method.toUpperCase()));
163	
164	  if (shouldSetContentType && !baseHeaders['Content-Type']) {
165	    baseHeaders['Content-Type'] = 'application/json';
166	  }
167	
168	  // Add custom headers (e.g., LastChangedUser for audit trails)
169	  if (lastChangedUser) {
170	    baseHeaders['LastChangedUser'] = lastChangedUser;
171	  }
172	
173	  // Inject auth header when the caller asked for it and the header is configured
174	  // via env vars captured during INTAKE Step 4b. Caller-provided headers win.
175	  if (requiresAuth) {
176	    const authHeader = getAuthHeader();
177	    if (authHeader && !(authHeader.name in baseHeaders)) {
178	      baseHeaders[authHeader.name] = authHeader.value;
179	    }
180	  }
181	
182	  return baseHeaders;
183	}
