340	/**
341	 * Creates a standardized APIError object
342	 */
343	function createAPIError(
344	  message: string,
345	  statusCode: number,
346	  details: string[],
347	  endpoint: string,
348	): APIError {
349	  return {
350	    message,
351	    statusCode,
352	    details,
353	    endpoint,
354	  };
355	}
