357	/**
358	 * Sanitizes request body for safe logging by removing sensitive fields
359	 * Customize the sensitiveFields array based on your application's needs
360	 */
361	function sanitizeBodyForLogging(body: BodyInit | null): unknown {
362	  if (!body) {
363	    return null;
364	  }
365	
366	  try {
367	    const parsed = JSON.parse(body as string);
368	    const sensitiveFields = [
369	      'password',
370	      'token',
371	      'apiKey',
372	      'secret',
373	      'creditCard',
374	      'ssn',
375	    ];
376	
377	    // Create a sanitized copy
378	    const sanitized = { ...parsed };
379	
380	    // Remove or mask sensitive fields
381	    Object.keys(sanitized).forEach((key) => {
382	      if (sensitiveFields.some((field) => key.toLowerCase().includes(field))) {
383	        sanitized[key] = '***REDACTED***';
384	      }
385	    });
386	
387	    return sanitized;
388	  } catch {
389	    return '[Unable to parse body]';
390	  }
391	}
392	
393	/**
394	 * Logs API request details in development mode
395	 * Automatically sanitizes sensitive fields for security
396	 */
397	function logRequest(url: string, method: string, body?: BodyInit | null): void {
398	  if (process.env.NODE_ENV === 'development') {
399	    console.group(`API Request: ${method} ${url}`);
400	    console.log('URL:', url);
401	    console.log('Method:', method);
402	
403	    if (body) {
404	      console.log('Body:', sanitizeBodyForLogging(body));
405	    }
406	
407	    console.groupEnd();
408	  }
409	}
410	
411	/**
412	 * Logs API response details in development mode
413	 */
414	function logResponse(response: Response): void {
415	  if (process.env.NODE_ENV === 'development') {
416	    const statusEmoji = response.ok ? '✅' : '❌';
417	    console.log(
418	      `${statusEmoji} API Response: ${response.status} ${response.statusText}`,
419	    );
420	  }
421	}
