/**
 * API Types - Generated from OpenAPI Spec
 *
 * AUTO-GENERATED by type-generator-agent from generated-docs/specs/api-spec.yaml
 * Do not edit manually - regenerate with /api-mock-refresh.
 *
 * These types correspond to the `components/schemas` section of the OpenAPI spec.
 * The existing base types (APIError, APIRequestConfig, etc.) remain in api.ts.
 */

export interface ErrorResponse {
  /** Human-readable error message */
  error: string;
  /** Machine-readable error code */
  code: string;
  /** Additional error details (e.g., validation errors) */
  details?: string[];
}

export type Role = 'Visitor' | 'Support Agent' | 'Admin';

export type EnquiryCategory = 'Feedback' | 'Question' | 'General Enquiry';

export type EnquiryStatus = 'New' | 'In Progress' | 'Resolved';

export interface LoginRequest {
  email: string;
  password: string;
}

export interface User {
  id: number;
  email: string;
  firstName: string;
  lastName: string;
  role: Role;
}

export interface SessionResponse {
  user: User;
  /** Role landing page (Visitor to Contact form; Support Agent and Admin to Inbox) */
  landingPath: string;
  /** 30 minutes after last activity */
  idleExpiresAt: string;
  /** 12 hours after sign-in */
  absoluteExpiresAt: string;
}

export interface Enquiry {
  id: number;
  name: string;
  email: string;
  address?: string | null;
  category: EnquiryCategory;
  comment: string;
  status: EnquiryStatus;
  /** Required when status is Resolved */
  replyNote?: string | null;
  submittedAt: string;
  submittedByEmail: string;
  handledBy?: string | null;
}

export interface EnquiryList {
  items: Enquiry[];
  total: number;
  limit: number;
  offset: number;
}

/**
 * API Endpoint Functions - Generated from OpenAPI Spec
 *
 * AUTO-GENERATED by type-generator-agent from generated-docs/specs/api-spec.yaml
 * Do not edit manually - regenerate with /api-mock-refresh.
 *
 * Each function wraps the project's API client with the correct path, method,
 * and TypeScript types from api-generated.ts.
 */

import { del, get, post } from '@/lib/api/client';
import type {
  Enquiry,
  EnquiryCategory,
  EnquiryList,
  EnquiryStatus,
  LoginRequest,
  SessionResponse,
} from '@/types/api-generated';

export type ListEnquiriesParams = {
  status?: EnquiryStatus;
  category?: EnquiryCategory;
  limit?: number;
  offset?: number;
};

/** POST /auth/login */
export const login = (data: LoginRequest) =>
  post<SessionResponse>('/auth/login', data);

/** POST /auth/logout */
export const logout = () => post<void>('/auth/logout');

/** GET /auth/session */
export const getSession = () => get<SessionResponse>('/auth/session');

/** GET /enquiries */
export const listEnquiries = (params?: ListEnquiriesParams) =>
  get<EnquiryList>('/enquiries', params);

/** GET /enquiries/{enquiryId} */
export const getEnquiry = (enquiryId: number) =>
  get<Enquiry>(`/enquiries/${enquiryId}`);

