93	/**
94	 * Builds the full URL with query parameters.
95	 *
96	 * Array values serialize as repeated params (`['a','b']` → `?k=a&k=b`); for
97	 * `explode: false` APIs, join at the endpoint-function layer. Empty arrays and
98	 * `undefined` values drop the key entirely (the "clear all filters" path). An
99	 * explicit empty string IS sent for scalars (`?k=`) — caller chose that. Array
100	 * items that are empty strings are dropped, since an array of empty strings is
101	 * never a meaningful filter selection.
102	 */
103	function buildUrl(endpoint: string, params?: QueryParams): string {
104	  const baseUrl = `${API_BASE_URL}${endpoint}`;
105	
106	  if (!params) {
107	    return baseUrl;
108	  }
109	
110	  const queryParams = new URLSearchParams();
111	  Object.entries(params).forEach(([key, value]) => {
112	    if (value === undefined) return;
113	    if (Array.isArray(value)) {
114	      value.forEach((item) => {
115	        if (item !== '') {
116	          queryParams.append(key, String(item));
117	        }
118	      });
119	      return;
120	    }
121	    queryParams.append(key, String(value));
122	  });
123	
124	  const queryString = queryParams.toString();
125	  return queryString ? `${baseUrl}?${queryString}` : baseUrl;
126	}
