185	/**
186	 * Reads auth-header configuration from env vars captured by api-connectivity-agent
187	 * during INTAKE Step 4b. Returns null when no token is configured (the request
188	 * proceeds without an Authorization header — useful in mock mode and on public
189	 * endpoints).
190	 *
191	 * Env var contract:
192	 * - NEXT_PUBLIC_API_AUTH_HEADER (default: "Authorization")
193	 * - NEXT_PUBLIC_API_AUTH_VALUE_PREFIX (default: "Bearer ", trailing space optional)
194	 * - NEXT_PUBLIC_API_TOKEN (the credential value)
195	 *
196	 * NEXT_PUBLIC_* vars are baked into the browser bundle. For production apps that
197	 * call a real backend with sensitive tokens, prefer a server-side auth layer or Next.js API route
198	 * proxy so tokens stay server-side. This helper is intended for local dev against
199	 * a dev backend where the convenience outweighs the exposure.
200	 */
201	export function getAuthHeader(): { name: string; value: string } | null {
202	  const token = process.env.NEXT_PUBLIC_API_TOKEN;
203	  if (!token) return null;
204	
205	  const name = process.env.NEXT_PUBLIC_API_AUTH_HEADER || 'Authorization';
206	  const rawPrefix = process.env.NEXT_PUBLIC_API_AUTH_VALUE_PREFIX;
207	  const prefix =
208	    rawPrefix === undefined
209	      ? 'Bearer '
210	      : rawPrefix.length > 0 && !rawPrefix.endsWith(' ')
211	        ? `${rawPrefix} `
212	        : rawPrefix;
213	
214	  return { name, value: `${prefix}${token}` };
215	}
