217	/**
218	 * Handles error responses from the API
219	 * Customize this function based on your API's error response format
220	 */
221	async function handleErrorResponse(
222	  response: Response,
223	  url: string,
224	): Promise<never> {
225	  const statusCode = response.status as HTTPStatusCode;
226	
227	  // Try to extract error details from response body
228	  let errorMessages: string[] = [];
229	  let defaultMessage = `HTTP ${statusCode}: ${response.statusText}`;
230	
231	  try {
232	    const contentType = response.headers.get('content-type');
233	    if (contentType && contentType.includes('application/json')) {
234	      const errorData = (await response.json()) as DefaultResponse;
235	
236	      if (errorData.Messages && errorData.Messages.length > 0) {
237	        errorMessages = errorData.Messages;
238	        defaultMessage = errorMessages[0];
239	      } else if (errorData.MessageType) {
240	        defaultMessage = `${errorData.MessageType}: ${defaultMessage}`;
241	      }
242	    }
243	  } catch {
244	    // If parsing fails, use default error message
245	  }
246	
247	  // Handle specific status codes
248	  // Customize these messages based on your application's needs
249	  switch (statusCode) {
250	    case 401:
251	      throw createAPIError(
252	        'Unauthorized: Please log in to continue',
253	        statusCode,
254	        errorMessages.length > 0
255	          ? errorMessages
256	          : ['Your session may have expired. Please log in again.'],
257	        url,
258	      );
259	
260	    case 403:
261	      throw createAPIError(
262	        'Forbidden: You do not have permission to perform this action',
263	        statusCode,
264	        errorMessages.length > 0 ? errorMessages : ['Access denied.'],
265	        url,
266	      );
267	
268	    case 404:
269	      throw createAPIError(
270	        'Not Found: The requested resource does not exist',
271	        statusCode,
272	        errorMessages.length > 0 ? errorMessages : ['Resource not found.'],
273	        url,
274	      );
275	
276	    case 500:
277	      throw createAPIError(
278	        'Internal Server Error: Something went wrong on the server',
279	        statusCode,
280	        errorMessages.length > 0
281	          ? errorMessages
282	          : [
283	              'Please try again later or contact support if the problem persists.',
284	            ],
285	        url,
286	      );
287	
288	    default:
289	      throw createAPIError(
290	        defaultMessage,
291	        statusCode,
292	        errorMessages.length > 0
293	          ? errorMessages
294	          : [`Request failed with status ${statusCode}`],
295	        url,
296	      );
297	  }
298	}
