 *
 * Tests for Epic 1 (sign-in-and-app-shell), Story 3: Session timeouts and account lockout.
 * Covers the lockout messaging on the sign-in screen (AC-1, AC-2). The time-driven
 * flows (lockout expiry, idle and absolute session timeouts) live in the Playwright spec.
 * These tests WILL FAIL until implemented (TDD red).
 */
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
// Import based on Story Metadata Target File — will fail until implemented (TDD red)
import LoginPage from '@/app/login/page';
import { get, post } from '@/lib/api/client';
// Project-wide identity source — never re-define seeded users here.
import { SEEDED_PASSWORD, seededUserFor } from '@/mocks/data/user';
import type { APIError } from '@/types/api';

vi.mock('@/lib/api/client', () => ({
  get: vi.fn(),
  post: vi.fn(),
  put: vi.fn(),
  del: vi.fn(),
  apiClient: vi.fn(),
}));

vi.mock('next/navigation', () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn(), refresh: vi.fn(), back: vi.fn() }),
  usePathname: () => '/login',
  useSearchParams: () => new URLSearchParams(),
  redirect: vi.fn(),
}));

const mockGet = get as ReturnType<typeof vi.fn>;
const mockPost = post as ReturnType<typeof vi.fn>;

const LOCKOUT_DURATION_MS = 15 * 60 * 1000;
const WRONG_PASSWORD = 'not-the-password';

/** The API client's rejection for a wrong email/password (spec: 401 INVALID_CREDENTIALS). */
const invalidCredentialsError = (): APIError => ({
  message: 'Unauthorized: Please log in to continue',
  statusCode: 401,
  details: ['Wrong email or password'],
  endpoint: '/auth/login',
});

/** The API client's rejection for a locked account (spec: 423 ACCOUNT_LOCKED; details carry the lockout end). */
const accountLockedError = (lockedUntil: Date): APIError => ({
  message: 'Account locked',
  statusCode: 423,
  details: [lockedUntil.toISOString()],
  endpoint: '/auth/login',
});

type UserEventInstance = ReturnType<typeof userEvent.setup>;

async function submitSignIn(user: UserEventInstance, email: string, password: string) {
  const emailField = screen.getByLabelText(/^email/i);
  await user.clear(emailField);
  await user.type(emailField, email);
  const passwordField = screen.getByLabelText(/^password/i);
  await user.clear(passwordField);
  await user.type(passwordField, password);
  await user.click(screen.getByRole('button', { name: /sign in/i }));
}

/** A failed sign-in has been processed once the password field is cleared (Story 1 AC-2). */
async function waitForFailedAttemptProcessed() {
  await waitFor(() => {
    expect(screen.getByLabelText(/^password/i)).toHaveValue('');
  });
}

describe('Epic 1, Story 3: Account lockout on the sign-in screen', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    // No active session while on the sign-in screen.
    mockGet.mockRejectedValue({
      message: 'Unauthorized: Please log in to continue',
      statusCode: 401,
      details: ['No active session'],
      endpoint: '/auth/session',
    } satisfies APIError);
  });

  // AC-1
  it('says the account is locked for 15 minutes on the 5th consecutive failed sign-in', async () => {
    const user = userEvent.setup();
    const agentEmail = seededUserFor('Support Agent').email;
    mockPost
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(accountLockedError(new Date(Date.now() + LOCKOUT_DURATION_MS)));

    render(<LoginPage />);

    for (let attempt = 1; attempt <= 4; attempt += 1) {
      await submitSignIn(user, agentEmail, WRONG_PASSWORD);
      await waitForFailedAttemptProcessed();
    }
    // After four failures the account is not yet locked — the wrong-credentials error shows.
    expect(screen.getByRole('alert')).toHaveTextContent(/incorrect/i);
    expect(screen.getByRole('alert')).not.toHaveTextContent(/locked/i);

    await submitSignIn(user, agentEmail, WRONG_PASSWORD);

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/locked/i);
    });
    expect(screen.getByRole('alert')).toHaveTextContent(/15 minutes/i);
  });

  // AC-2
  it('refuses the correct password while the account is locked and shows the locked message again', async () => {
    const user = userEvent.setup();
    const adminEmail = seededUserFor('Admin').email;
    const lockedUntil = new Date(Date.now() + LOCKOUT_DURATION_MS);
    mockPost
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(invalidCredentialsError())
      .mockRejectedValueOnce(accountLockedError(lockedUntil))
      .mockRejectedValueOnce(accountLockedError(lockedUntil));

    render(<LoginPage />);

    for (let attempt = 1; attempt <= 5; attempt += 1) {
      await submitSignIn(user, adminEmail, WRONG_PASSWORD);
      await waitForFailedAttemptProcessed();
    }
    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/locked/i);
    });

    await submitSignIn(user, adminEmail, SEEDED_PASSWORD);
    await waitForFailedAttemptProcessed();

    // Still on the sign-in screen, with the locked message rather than a successful sign-in.
    expect(screen.getByRole('button', { name: /sign in/i })).toBeInTheDocument();
    expect(screen.getByRole('alert')).toHaveTextContent(/locked/i);
    expect(screen.getByRole('alert')).toHaveTextContent(/15 minutes/i);
  });
});

/**
 * Story Metadata:
 * - Route: /login
 * - Target File: web/src/app/(authenticated)/layout.tsx
 * - Sign-in form under test: web/src/components/auth/SignInForm.tsx
 *   (a client component rendered by web/src/app/login/page.tsx that calls
 *   `login()` from @/lib/api/endpoints, i.e. `post('/auth/login', ...)`)
 *
 * Epic sign-in-and-app-shell, Story 1: Sign in, land on your page, and sign out.
 * Covers the sign-in failure states (wrong credentials vs connection problem).
 * These tests WILL FAIL until implemented (TDD red).
 */
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';

import { SignInForm } from '@/components/auth/SignInForm';
import { post } from '@/lib/api/client';
import { seededUserFor } from '@/mocks/data/user';
import type { APIError } from '@/types/api';

vi.mock('@/lib/api/client', () => ({ get: vi.fn(), post: vi.fn() }));

vi.mock('next/navigation', () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn(), refresh: vi.fn() }),
  usePathname: () => '/login',
  useSearchParams: () => new URLSearchParams(),
}));

const mockPost = post as ReturnType<typeof vi.fn>;

/** The error the API client throws when /auth/login answers 401 (wrong email or password). */
const wrongCredentialsError: APIError = {
  message: 'Unauthorized: Please log in to continue',
  statusCode: 401,
  details: ['Your session may have expired. Please log in again.'],
  endpoint: '/auth/login',
};

/** The error the API client throws when the sign-in service cannot be reached. */
const connectionFailureError: APIError = {
  message: 'Network error: Unable to connect to the API server',
  statusCode: 0,
  details: ['Please check your internet connection and try again.'],
  endpoint: '/auth/login',
};

const visitor = seededUserFor('Visitor');

async function submitSignIn(email: string, password: string) {
  const user = userEvent.setup();
  render(<SignInForm />);
  await user.type(screen.getByLabelText(/^email/i), email);
  await user.type(screen.getByLabelText(/^password/i), password);
  await user.click(screen.getByRole('button', { name: /sign in/i }));
}

describe('Epic sign-in-and-app-shell, Story 1: sign-in failures', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // AC-2
  it('shows an inline wrong-credentials error, keeps the email, clears the password and focuses the error summary', async () => {
    mockPost.mockRejectedValue(wrongCredentialsError);

    await submitSignIn(visitor.email, 'NotTheRightPassword1');

    const errorSummary = await screen.findByRole('alert');
    expect(errorSummary).toHaveTextContent(/email or password is incorrect/i);
    await waitFor(() => {
      expect(errorSummary).toHaveFocus();
    });
    expect(screen.getByLabelText(/^email/i)).toHaveValue(visitor.email);
    expect(screen.getByLabelText(/^password/i)).toHaveValue('');
  });

  // AC-3
  it('shows a connection-problem error, distinct from the wrong-credentials error, when the sign-in service cannot be reached', async () => {
    mockPost.mockRejectedValue(connectionFailureError);

    await submitSignIn(visitor.email, 'Test123');

    const errorSummary = await screen.findByRole('alert');
    expect(errorSummary).toHaveTextContent(/connection/i);
    expect(errorSummary).not.toHaveTextContent(/email or password is incorrect/i);
  });
});

/**
 * Story Metadata:
 * - Route: /login
 * - Target File: web/src/app/login/page.tsx
 *
 * Mocking strategy:
 * - Backend calls are ALWAYS mocked — this spec never contacts a live backend
 *   (see testing-policy.md § "Playwright runs against mocks, never live").
 *   Intercept via: MSW (wired at web/src/mocks/, started by MockProvider when
 *   NEXT_PUBLIC_USE_MOCK_API=true). The MSW handlers compose the shared mock data
 *   (seededUsers / SEEDED_PASSWORD from mocks/data/user, userInfoFor from
 *   mocks/data/identity), so this spec authors no response bodies of its own.
 * - Implementation pattern this assumes:
 *   - Sign-in calls POST /auth/login from the browser through the API client, so the
 *     browser MSW worker answers it (401 INVALID_CREDENTIALS, 423 ACCOUNT_LOCKED,
 *     200 SessionResponse).
 *   - Per BR6 the idle (30 min) and absolute (12 h) session timers and the 15-minute
 *     lockout window are evaluated in the browser against Date.now()/browser timers,
 *     so page.clock drives them with the REAL configured durations — no test-only
 *     shortened durations in production code.
 *   - "Activity" that resets the idle timer includes pointer movement and key presses.
 *   - On expiry the app navigates to /login and shows a "session expired" message.
 *   - A failed sign-in clears the password field (Story 1 AC-2); the spec uses that to
 *     know each attempt has been processed.
 * - If the implementation diverges from these assumptions, this spec will not pass.
 *
 * E2E spec for Epic 1 (sign-in-and-app-shell), Story 3: Session timeouts and account lockout.
 * These tests WILL FAIL until implemented (TDD red).
 */
import { test, expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
// Shared identity source — relative imports, not @/.
import { LANDING_PATH_BY_ROLE } from '../src/mocks/data/identity';
import { SEEDED_PASSWORD, seededUserFor } from '../src/mocks/data/user';

import type { Page } from '@playwright/test';

const WRONG_PASSWORD = 'not-the-password';
const WCAG_22_AA_TAGS = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'];

const landingPathPattern = (landingPath: string) => new RegExp(`${landingPath}$`);

async function submitSignIn(page: Page, email: string, password: string): Promise<void> {
  await page.getByLabel(/^email/i).fill(email);
  await page.getByLabel(/^password/i).fill(password);
  await page.getByRole('button', { name: /sign in/i }).click();
}

async function submitFailedSignIn(page: Page, email: string, password: string): Promise<void> {
  await submitSignIn(page, email, password);
  await expect(page.getByLabel(/^password/i)).toHaveValue('');
}

const sessionExpiredMessage = (page: Page) => page.getByText(/session (has )?expired/i);

test.describe('Epic 1, Story 3: Session timeouts and account lockout', () => {
  test.beforeEach(async ({ context }) => {
    await context.clearCookies();
  });

  // AC-3
  test('a locked account can sign in with the correct password once 15 minutes have passed', async ({
    page,
  }) => {
    const agent = seededUserFor('Support Agent');
    await page.clock.install();
    await page.goto('/login');

    for (let attempt = 1; attempt <= 5; attempt += 1) {
      await submitFailedSignIn(page, agent.email, WRONG_PASSWORD);
    }
    const lockedAlert = page.getByRole('alert').filter({ hasText: /locked/i });
    await expect(lockedAlert).toBeVisible();
    await expect(lockedAlert).toContainText(/15 minutes/i);

    // Locked state is accessible.
    const { violations } = await new AxeBuilder({ page }).withTags(WCAG_22_AA_TAGS).analyze();
    expect(violations).toEqual([]);

    // Just short of the lockout window, the correct password is still refused.
    await page.clock.fastForward('14:00');
    await submitFailedSignIn(page, agent.email, SEEDED_PASSWORD);
    await expect(lockedAlert).toBeVisible();

    // Past the 15-minute lockout, the correct password signs in to the role's page.
    await page.clock.fastForward('01:05');
    await submitSignIn(page, agent.email, SEEDED_PASSWORD);
    await expect(page).toHaveURL(landingPathPattern(LANDING_PATH_BY_ROLE['Support Agent']));
  });

  // AC-4
  test('after 30 minutes with no activity, the user is returned to sign-in with a session-expired message', async ({
    page,
  }) => {
    const visitor = seededUserFor('Visitor');
    await page.clock.install();
    await page.goto('/login');
    await submitSignIn(page, visitor.email, SEEDED_PASSWORD);
    const landingPath = landingPathPattern(LANDING_PATH_BY_ROLE.Visitor);
    await expect(page).toHaveURL(landingPath);

    // Not yet idle for 30 minutes — still signed in.
    await page.clock.fastForward('29:00');
    await expect(page).toHaveURL(landingPath);
    await expect(sessionExpiredMessage(page)).toBeHidden();

    // Crossing the 30-minute idle limit ends the session.
    await page.clock.fastForward('01:05');
    await expect(page).toHaveURL(/\/login/);
    await expect(sessionExpiredMessage(page)).toBeVisible();

    // Session-expired state is accessible.
    const { violations } = await new AxeBuilder({ page }).withTags(WCAG_22_AA_TAGS).analyze();
    expect(violations).toEqual([]);
  });

  // AC-5
  test('a user who keeps working is still signed out with the session-expired message after 12 hours', async ({
    page,
  }) => {
    const admin = seededUserFor('Admin');
    await page.clock.install();
    await page.goto('/login');
    await submitSignIn(page, admin.email, SEEDED_PASSWORD);
    const landingPath = landingPathPattern(LANDING_PATH_BY_ROLE.Admin);
    await expect(page).toHaveURL(landingPath);

    // Stay active: 24 × 29 minutes = 11 h 36 min, with activity before each idle limit.
    for (let interval = 1; interval <= 24; interval += 1) {
      await page.clock.fastForward('29:00');
      await page.mouse.move(100 + interval, 200 + interval);
      await page.keyboard.press('Shift');
    }
    await expect(page).toHaveURL(landingPath);
    await expect(sessionExpiredMessage(page)).toBeHidden();

    // 24 min 30 s later: past the 12-hour cap, yet well inside the 30-minute idle window.
    await page.clock.fastForward('24:30');
    await expect(page).toHaveURL(/\/login/);
    await expect(sessionExpiredMessage(page)).toBeVisible();
  });
});

/**
 * Story Metadata:
 * - Route: /login
 * - Target File: web/src/app/(authenticated)/layout.tsx
 *
 * Mocking strategy:
 * - Backend calls are ALWAYS mocked — this spec never contacts a live backend
 *   (testing-policy.md § "Playwright runs against mocks, never live"). The project
 *   is mock-only (project.md §Data Source): there is no backend at all.
 *   Intercept via: MSW (web/src/mocks/ is wired — MockProvider starts the browser
 *   worker when NEXT_PUBLIC_USE_MOCK_API=true, set in web/.env.local).
 *   - The MSW handlers in web/src/mocks/handlers.ts answer /auth/login, /auth/session
 *     and /auth/logout from the shared seeded users and `userInfoFor(role)`, so the
 *     spec installs no page.route() of its own and authors no response bodies.
 *   - Form-fill identities come from the shared seed (../src/mocks/data/user) and the
 *     expected landing pages from ../src/mocks/data/identity — never hard-coded.
 * - Implementation pattern this assumes:
 *   - The sign-in form is a client component that calls `login()` from the browser
 *     through the API client (so MSW intercepts it), and must not submit before
 *     the MSW worker has started.
 *   - A successful sign-in leaves a same-origin `session` cookie that the
 *     (authenticated) layout checks server-side; with no session, every app page
 *     (including `/`) redirects to /login.
 *   - Sign-out is a "Sign out" button in the authenticated shell that clears the
 *     session cookie and lands on /login; protected pages must not be restorable
 *     from the browser's back/forward cache once signed out.
 * - If the implementation diverges from these assumptions, this spec will not pass.
 *
 * E2E spec for Epic sign-in-and-app-shell, Story 1: Sign in, land on your page, and sign out.
 * These tests WILL FAIL until implemented (TDD red).
 */
import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';

import { LANDING_PATH_BY_ROLE } from '../src/mocks/data/identity';
import { SEEDED_PASSWORD, seededUserFor } from '../src/mocks/data/user';

import type { Page } from '@playwright/test';
import type { Role } from '../src/types/api-generated';

/** NFR-base-1: WCAG 2.2 Level AA. */
const WCAG_22_AA_TAGS = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'];

const SEEDED_ROLES: readonly Role[] = ['Visitor', 'Support Agent', 'Admin'];

const pathnameIs = (expectedPathname: string) => (url: URL) =>
  url.pathname === expectedPathname;

const signInHeading = (page: Page) => page.getByRole('heading', { name: /sign in/i });

async function signInAs(page: Page, role: Role): Promise<void> {
  await page.goto('/login');
  await expect(signInHeading(page)).toBeVisible();
  await page.getByLabel(/^email/i).fill(seededUserFor(role).email);
  await page.getByLabel(/^password/i).fill(SEEDED_PASSWORD);
  await page.getByRole('button', { name: /sign in/i }).click();
}

test.describe('Epic sign-in-and-app-shell, Story 1: Sign in, land on your page, and sign out', () => {
  test.beforeEach(async ({ context }) => {
    await context.clearCookies();
  });

  // AC-1
  test('each seeded account lands on its role page after signing in', async ({ browser }) => {
    for (const role of SEEDED_ROLES) {
      const context = await browser.newContext();
      const page = await context.newPage();

      await signInAs(page, role);
      await expect(page).toHaveURL(pathnameIs(LANDING_PATH_BY_ROLE[role]));

      await context.close();
    }
  });

  // AC-4
  test('a signed-out user opening any app URL, including the root, is sent to sign-in', async ({
    page,
  }) => {
    for (const appPath of ['/', '/contact', '/my-messages', '/inbox']) {
      await page.goto(appPath);
      await expect(page).toHaveURL(pathnameIs('/login'));
      await expect(signInHeading(page)).toBeVisible();
      await expect(page.getByRole('heading', { name: 'Welcome' })).toBeHidden();
    }
  });

  // AC-5
  test('after signing out, the Back button returns to sign-in rather than the previous app page', async ({
    page,
  }) => {
    await signInAs(page, 'Visitor');
    await expect(page).toHaveURL(pathnameIs(LANDING_PATH_BY_ROLE.Visitor));

    await page.getByRole('button', { name: /sign out/i }).click();
    await expect(page).toHaveURL(pathnameIs('/login'));
    await expect(signInHeading(page)).toBeVisible();

    await page.goBack();
    await expect(page).toHaveURL(pathnameIs('/login'));
    await expect(signInHeading(page)).toBeVisible();
    await expect(page.getByRole('button', { name: /sign out/i })).toBeHidden();
  });

  // AC-6
  test('the sign-in screen is accessible, labelled and completable with the keyboard alone', async ({
    page,
  }) => {
    const emailField = page.getByLabel(/^email/i);
    const passwordField = page.getByLabel(/^password/i);
    const signInButton = page.getByRole('button', { name: /sign in/i });

    // Default state: settled, labelled, no violations.
    await page.goto('/login');
    await expect(signInHeading(page)).toBeVisible();
    await expect(emailField).toBeVisible();
    await expect(passwordField).toBeVisible();
    await expect(passwordField).toHaveAttribute('type', 'password');
    const defaultScan = await new AxeBuilder({ page }).withTags(WCAG_22_AA_TAGS).analyze();
    expect(defaultScan.violations).toEqual([]);

    // Error state: a wrong-password submit shows the error summary with no violations.
    await emailField.fill(seededUserFor('Visitor').email);
    await passwordField.fill(`${SEEDED_PASSWORD}-wrong`);
    await signInButton.click();
    await expect(page.getByRole('alert').filter({ hasText: /incorrect/i })).toBeVisible();
    const errorScan = await new AxeBuilder({ page }).withTags(WCAG_22_AA_TAGS).analyze();
    expect(errorScan.violations).toEqual([]);

    // Keyboard only: Tab to each field, type, and submit with Enter.
    await page.goto('/login');
    await expect(signInHeading(page)).toBeVisible();
    await page.keyboard.press('Tab');
    await expect(emailField).toBeFocused();
    await page.keyboard.type(seededUserFor('Support Agent').email);
    await page.keyboard.press('Tab');
    await expect(passwordField).toBeFocused();
    await page.keyboard.type(SEEDED_PASSWORD);
    await page.keyboard.press('Tab');
    await expect(signInButton).toBeFocused();
    await page.keyboard.press('Enter');
    await expect(page).toHaveURL(pathnameIs(LANDING_PATH_BY_ROLE['Support Agent']));
  });
});

/**
 * Epic baseline: sign-in-and-app-shell
 *
 * Cross-story invariants for the authenticated app shell introduced in Story 1
 * (web/src/app/(authenticated)/layout.tsx renders the shell around every app page).
 * Later stories in this epic extend this file only with genuinely new shared-surface
 * invariants; they do not re-assert these.
 *
 * Shell under test: web/src/components/layout/AppShell.tsx — a component taking the
 * signed-in `session` (the SessionResponse from /auth/session) and the page content.
 * These tests WILL FAIL until implemented (TDD red).
 */
import { render, screen, within } from '@testing-library/react';
import { vi, describe, it, expect } from 'vitest';

import { AppShell } from '@/components/layout/AppShell';
import { userInfoFor } from '@/mocks/data/identity';

vi.mock('@/lib/api/client', () => ({ get: vi.fn(), post: vi.fn() }));

vi.mock('next/navigation', () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn(), refresh: vi.fn() }),
  usePathname: () => '/',
  useSearchParams: () => new URLSearchParams(),
}));

describe('Epic sign-in-and-app-shell baseline: authenticated app shell', () => {
  // Runtime-only: the (authenticated) layout composing this shell around every page is verified during manual checklist
  // AC-5 (Story 1)
  it.each(['Visitor', 'Support Agent', 'Admin'])(
    'gives a signed-in %s a Sign out control alongside the page content',
    (roleName) => {
      render(
        <AppShell session={userInfoFor(roleName)}>
          <section aria-label="Page content">Landing page body</section>
