      const pageContent = screen.getByRole('region', { name: 'Page content' });
      expect(within(pageContent).getByText('Landing page body')).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /sign out/i })).toBeInTheDocument();
    },
  );
});

